  const mapped = {};
  for (const [miyarField, crmField] of Object.entries(mapping)) {
    if (data[miyarField] !== void 0) {
      mapped[crmField] = data[miyarField];
    }
  }
  for (const [key, value] of Object.entries(data)) {
    if (!mapping[key]) {
      mapped[key] = value;
    }
  }
